public class RepeatJoiner {

    public static String repeatJoin(String word, int n, String sep) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                result.append(sep);
            }
            result.append(word);
        }
        return result.toString();
    }
}
